// Parse incoming CSV rows from webhook body
// Expected: { csv: "<base64 or raw CSV string>", filename: "xyz.csv" }
const body = $input.first().json.body || $input.first().json;
const csvText = body.csv_data || body.csv || '';
const filename = body.filename || 'uploaded.csv';

if (!csvText) {
  throw new Error('No CSV data received');
}

// Simple CSV parser
function parseCSV(text) {
  const lines = text.trim().split('\n');
  const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/[^a-z0-9_]/g,'_'));
  return lines.slice(1).filter(l => l.trim()).map(line => {
    // Handle quoted fields
    const vals = [];
    let cur = '', inQ = false;
    for (const ch of line) {
      if (ch === '"') { inQ = !inQ; }
      else if (ch === ',' && !inQ) { vals.push(cur.trim()); cur = ''; }
      else { cur += ch; }
    }
    vals.push(cur.trim());
    const obj = {};
    headers.forEach((h, i) => obj[h] = vals[i] || '');
    return obj;
  });
}

const rows = parseCSV(csvText);
return rows.map(r => ({ json: { ...r, _filename: filename } }));

// Normalize email and phone for matching
const row = $input.first().json;

function normalizeEmail(e) {
  if (!e) return null;
  return e.trim().toLowerCase().replace(/^alt\./, '');
}

function normalizePhone(p) {
  if (!p) return null;
  const d = p.replace(/\D/g, '');
  if (d.length === 12 && d.startsWith('91')) return d.slice(2);
  if (d.length === 11 && d.startsWith('0')) return d.slice(1);
  if (d.length === 10) return d;
  return null;
}

// Try to find email in multiple common column names
const email = normalizeEmail(
  row.email || row.email_id || row.e_mail || row.mail || ''
);
const phone = normalizePhone(
  row.phone || row.phone_number || row.mobile || row.contact || ''
);
const name = (row.full_name || row.worker_name || row.name || '').trim();

return [{ json: { ...row, _norm_email: email, _norm_phone: phone, _norm_name: name } }];

// Filter the full persons list for a match on email OR phone
const incoming = $('Normalize Fields').first().json;
const allPersons = $input.first().json;

const matches = (Array.isArray(allPersons) ? allPersons : []).filter(p => {
  const emailMatch = incoming._norm_email && p.email && p.email.toLowerCase() === incoming._norm_email;
  const phoneMatch = incoming._norm_phone && p.phone && p.phone === incoming._norm_phone;
  return emailMatch || phoneMatch;
});

return [{ json: { matches, match_count: matches.length, incoming } }];

// Build duplicate alert message
const incoming = $('Normalize Fields').first().json;
const matches  = $input.all().map(i => i.json);

const msg = [
  `🔴 *Duplicate Alert — ConsultBae CSV Checker*`,
  ``,
  `*Incoming record:*`,
  `• Name:  ${incoming._norm_name || '—'}`,
  `• Email: ${incoming._norm_email || '—'}`,
  `• Phone: ${incoming._norm_phone || '—'}`,
  `• File:  ${incoming._filename || '—'}`,
  ``,
  `*Matched existing records (${matches.length}):*`,
  ...matches.map((m,i) => `${i+1}. ${m.name} | ${m.email||'—'} | ${m.phone||'—'} | sources: ${m.sources||'—'}`),
].join('\n');

return [{ json: { alert_message: msg, incoming, matches } }];

// Tag the record as new — optionally insert it
const row = $input.first().json;
return [{ json: { status: 'new_record', record: row } }];
